import { gs, GlideRecord, GlideDateTime } from '@servicenow/glide';
export function setImpactDueDate(current, previous) {
    var eventId = current.getValue('event');
    if (!eventId)
        return;
    var evt = new GlideRecord('x_2248447_csr_ma_2_event');
    if (!evt.get(eventId))
        return;
    var eventDate = evt.getValue('event_date');
    if (!eventDate)
        return;
    var dueDays = parseInt(gs.getProperty('x_2248447_csr_ma_2.impact_due_days')) || 15;
    var dueDate = new GlideDateTime(eventDate);
    dueDate.addDaysUTC(dueDays);
    current.setValue('due_date', dueDate.getValue());
    current.setValue('status', 'pending');
}
export function partnerScoreOnOverdue(current, previous) {
    var newFlag = current.getValue('overdue_flag');
    var oldFlag = previous.getValue('overdue_flag');
    if (newFlag !== 'true' && newFlag !== true)
        return;
    if (oldFlag === 'true' || oldFlag === true)
        return;
    var partnerId = current.getValue('partner');
    if (!partnerId)
        return;
    var partner = new GlideRecord('x_2248447_csr_ma_2_partner');
    if (partner.get(partnerId)) {
        var overdue = parseInt(partner.getValue('overdue_reports')) || 0;
        overdue++;
        partner.setValue('overdue_reports', overdue);
        // Score recalculation happens via partner BR
        partner.update();
        gs.info('CSR: Partner ' + partner.getValue('name') + ' overdue reports incremented to ' + overdue);
    }
}
export function validateVerifiedBeneficiaries(current, previous) {
    var verified = parseInt(current.getValue('beneficiaries_verified')) || 0;
    var reported = parseInt(current.getValue('beneficiaries_reported')) || 0;
    if (verified > reported) {
        current.setValue('beneficiaries_verified', reported);
        gs.addInfoMessage('Verified beneficiaries capped at reported amount (' + reported + ').');
    }
}
